from shop.store.base import InMemoryCollection
from shop.errors import NotFound

class CouponStore:
    def __init__(self):
        self._coupons = InMemoryCollection()

    def save(self, coupon):
        """Store and return the coupon."""
        self._coupons[coupon.code] = coupon
        return coupon

    def get(self, code):
        """Return the coupon or raise NotFound."""
        return self._coupons[code]

    def exists(self, code):
        """Check if a coupon exists."""
        return code in self._coupons
